import sys, re
sys.path.insert(0, "outputs/prior-capture/work")
from cap import Fill, _clean
c = Fill(30, "M02")
S = lambda key, text, lines, **kw: c.f(key, kw.pop("kind", "statement"), text, lines, **kw)
S("n19", "Links that do not count are non-inner-being senses of the M47 word: Pro 25:23, Eze 13:13, 19:12 and Psa 11:6 (wind); Num 11:33 (meat); Eze 16:26 (lustful \"flesh\"); Eze 7:19 (nephesh as hunger); Psa 124:5 (\"us\"); Est 8:11 (lives as targets); no M02 Strong's loses its implicit status through this.", [19], kind="silence")
S("n24", "saar H5590 \"rage\" is mostly the sea raging (Jon 1:11, 13).", [24], kind="term")
S("t32", "In the vice lists with thumos (2Cor 12:20; Gal 5:20; Eph 4:31; Col 3:8) the inner place is given by the list's frame, not by a seat: in Gal 5:19 anger is among \"the works of the flesh\", with 5:17 (flesh against Spirit) nearby; in Col 3:8 it is put away along with speech \"from your mouth\"; flesh and mouth take the seat's place.", [32], basis="read")
S("t33", "In crowd rage (Luk 4:28, \"all in the synagogue were filled with wrath\"; Act 19:28, \"enraged and ... crying out, 'Great is Artemis'\") the collective is the container: \"filled\", with no organ named; the shout carries it.", [33], basis="read")
S("t35", "Divine wrath in Revelation (14:10, 19; 15:1, 7; 16:1, 19; 19:15) becomes a substance: wine, a cup, bowls, a winepress; the human side is drinking it (14:10; 16:19); in Rev 14:8 and 18:3 \"the wine of the passion of her sexual immorality\" the same word means intoxicating passion, and the drinking image is shared with God's wrath.", [35], kind="term", verses=["Rev.14.10", "Rev.16.19", "Rev.14.8", "Rev.18.3"], flag="the divine-wrath bullet, line 34, whose references are bare")
S("t36", "Heb 11:27 is a no-seat verse about Moses's inner operation (faith, not being afraid); the king's anger is only its occasion: \"for he endured as seeing him who is invisible\".", [36])
S("a40", "Indignation (aganakteō) is a reaction triggered by something seen or heard: \"when the ten heard it\" (Mat 20:24; Mar 10:41); \"when the chief priests ... saw\" (Mat 21:15); \"when the disciples saw it\" (Mat 26:8); \"when Jesus saw it\" (Mar 10:14).", [40])
S("a41", "Indignation is carried by speech (\"Why this waste?\", Mat 26:8); in Mar 14:4, \"said to themselves indignantly\" (pros heautous), the inner place is given by a reflexive pronoun; the status rivalry between disciples (Mat 20:24; Mar 10:41) is relational.", [41], basis="read")
S("a42", "Luk 13:14: the synagogue ruler, indignant at Jesus, turns and addresses the crowd; the anger is displaced onto a third party.", [43], basis="read", verses=["Luke.13.14"], flag="the Luk 13:14 bullet, line 42")
S("a43", "2Cor 7:11 lists \"what indignation, what fear, what longing, what zeal\" as the fruit of \"godly grief\", a sequence of inner operations valued as good; Mar 10:14 is Jesus's indignation, and the bearer class is recorded as divine in the party data, noted and not resolved.", [43])
S("o48", "Anger turns straight into action, especially in the parables and in narrative: \"in anger his master delivered him to the jailers\" (Mat 18:34); \"The king was angry, and he sent his troops\" (Mat 22:7); the master \"became angry and said ... bring in the poor\" (Luk 14:21); Herod \"became furious, and he sent and killed all the male children\" (Mat 2:16); there is no interval in which a seat would be named, and the act is the evidence of the state.", [48, 49, 50, 51], basis="read")
S("o54", "Luk 15:28: the elder brother \"was angry and refused to go in\"; his father came out and entreated him; the complaint that follows (15:29-30) exposes a hidden grievance, \"these many years I have served you\": the inner state was held behind service, and anger releases it (hidden-behind-act).", [54], basis="read")
S("o55", "In Mat 5:21-22 anger is set beside murder, and incurs the same \"liable to judgment\".", [55])
S("o56", "Anger is bounded by time in Eph 4:26-27, \"Be angry and do not sin; do not let the sun go down on your anger, and give no opportunity to the devil\"; the neighbouring 4:23 has \"renewed in the spirit of your minds\", and the implicit seat is the passage's.", [56], basis="read")
S("o57", "Cholaō (Joh 7:23) is built on cholē, \"bile\": the Greek carries an inner organ inside the verb, as thumos does.", [57], kind="term")
S("o58", "Relational causation: in Eph 6:4 fathers \"provoke to anger\" (parorgizō), exactly parallel to Col 3:21 (provoke, discouraged); in Rom 10:19 God provokes Israel to jealousy and anger, an inner operation induced from outside, with God as the cause.", [58], basis="read")
S("f63", "Gen 4:5-6: \"Cain was very angry, and his face fell ... Why are you angry, and why has your face fallen?\"; God reads the anger off the face; what follows in 4:7 is an inner struggle stated as an image: \"sin is crouching at the door. Its desire is for you, and you must rule over it\".", [63])
S("f63b", "Dan 3:19: \"Nebuchadnezzar was filled with fury, and the expression of his face was changed\"; the rage is externalised onto the furnace, \"heated seven times more\".", [63], verses=["Dan.3.19"], flag="the Daniel bullet, line 64")
S("f65", "1Ki 21:4: Ahab went home \"vexed and sullen ... lay down on his bed and turned away his face and would eat no food\"; in 21:5 Jezebel says, \"Why is your spirit so vexed that you eat no food?\"; the narrator gives no seat, and the wife names one, reading it off the body (1Ki 20:43, \"vexed and sullen\", is the same pair).", [65], basis="read")
S("f68a", "1Sa 20:34: Jonathan \"rose from the table in fierce anger and ate no food ... for he was grieved for David\"; anger, grief and fasting come together.", [68], verses=["1Sam.20.34"], flag="the Jonathan bullet, line 67")
S("f68", "2Ki 5:11-14: Naaman \"was angry and went away ... turned and went away in a rage\"; his inner thought is quoted (\"Behold, I thought that he would surely come out\"); the servants talk him round (5:13), and \"his flesh was restored like the flesh of a little child\" (5:14): rage, persuasion, obedience, restoration, with no seat word anywhere.", [68])
S("f69", "2Ch 16:10 (Asa \"in a rage with\" the seer) and Dan 2:12 (the king \"angry and very furious\"): anger issues in orders, imprisonment and execution.", [69])
S("f70", "Jer 3:12, \"I will not look on you in anger\", is literally \"cause my face to fall\": the same body idiom is used of God.", [70], kind="term")
S("e75", "The strife words are mostly in vice lists and church-order texts, where the inner place is given by the frame: 1Cor 3:3, \"you are still of the flesh\"; 1Ti 6:4-5, \"puffed up with conceit ... depraved in mind\" (nous is excluded from M47 by ruling 4, so these do not count as seated); Gal 5:26 (\"provoking one another, envying one another\") sits between 5:24-25 (flesh crucified, walk by the Spirit) and 6:1.", [75, 76, 77], basis="read")
S("e78", "Phili 1:15, \"Some indeed preach Christ from envy and rivalry, but others from good will\": the same act has different inner sources.", [78])
S("e80", "The same word has opposite value: paroxusmos is the \"sharp disagreement\" that parts Paul and Barnabas (Act 15:39) and also \"stir up one another to love and good works\" (Heb 10:24); erethizō is \"your zeal has stirred up most of them\" (2Cor 9:2) and also \"do not provoke your children\" (Col 3:21).", [80, 81], kind="use")
S("a87", "Ashan, \"smoke\", is literally smoke when it is the anger word: Sinai \"wrapped in smoke\" (Exo 19:18), mountains that \"smoke\" at his touch (Psa 104:32; 144:5); where it is anger it is divine anger answering a human heart: \"the anger of the Lord and his jealousy will smoke against that man\" (Deu 29:20), the man of 29:18-19 \"whose heart is turning away ... blesses himself in his heart, saying, 'I shall be safe, though I walk in the stubbornness of my heart'\"; the seat in the passage is the human's secret self-blessing, and the anger answers it.", [87], basis="read")
S("a88", "Meribah is a place name that stores an inner event (\"the waters of Meribah, where the people of Israel quarreled with the Lord\", Num 20:13); in Eze 47:19 and 48:28 it is a boundary marker with no inner content left; in Psa 106:32 the next verse is seated (106:33, \"they made his spirit bitter\", Moses's spirit).", [88], kind="term")
S("a89", "Gen 13:8: \"Let there be no strife between you and me ... for we are kinsmen\": strife refused on the ground of kinship.", [89])
S("a90", "Job's vexation (ka'as H3708B): \"Oh that my vexation were weighed\" (6:2) and \"my eye has grown dim from vexation\" (17:7); the eye carries it, and the whole body, \"all my members are like a shadow\"; Job 5:2, \"vexation kills the fool\", shows the inner state as lethal.", [90])
S("a91", "Rev 3:15-16, zestos: \"Neither hot nor cold ... lukewarm ... I will spit you out of my mouth\": the inner state is given as temperature, and the response as the body rejecting food.", [91], basis="read")
for n in (99, 100, 101):
    x = [_clean(y) for y in c.by_line[n]["text"].strip().strip("|").split(" | ")]
    S(f"w{n}", f"Whose seat the anger points to, {x[0]}: genuine links {x[1]}. What it implies for the no-seat verses: {x[2]}.", [n], basis="read")
S("s106", "Neh 5:6-7: \"I was very angry when I heard their outcry ... I took counsel with myself\" (Hebrew: my heart counselled me): the anger is followed by deliberation, and the seat arrives with the deliberation.", [106])
S("s107", "1Sa 1:6-7 (ka'as, Hannah provoked, \"wept and would not eat\") is followed in 1:15-16 by \"a woman troubled in spirit ... pouring out my soul ... speaking out of my great anxiety and vexation\": the seat is given by the sufferer herself when she explains her behaviour.", [107])
S("s110", "Est 1:12, \"his anger burned within him\" (Hebrew bo, \"in him\"), has a pronoun and no seat word; Est 3:5 has Haman \"filled with fury\", and Est 5:9 is the same scene seated, \"joyful and glad of heart. But when Haman saw Mordecai ... he was filled with wrath\": the implicit seat for 3:5 is Haman's own heart, established two chapters later.", [110], basis="read", verses=["Esth.3.5", "Esth.5.9", "Esth.1.12"])
S("s111", "Jon 4:1-3: \"it displeased Jonah exceedingly, and he was angry. And he prayed ... I knew that you are a gracious God ... slow to anger ... please take my life from me\": Jonah quotes God's own \"slow to anger\" against him, so the anger comes from a creed he knows well; God's reply, \"Do you do well to be angry?\" (4:4, 9), leads to \"angry enough to die\".", [111])
S("s113", "Anger with an act: Moses \"saw the calf ... anger burned hot, and he threw the tablets\" (Exo 32:19); Balaam struck the donkey (Num 22:27); Balak \"struck his hands together\" (Num 24:10); Saul's verbal assault on Jonathan (1Sa 20:30); David's verdict on the rich man, \"the man who has done this deserves to die\" (2Sa 12:5), which the next verse turns: \"You are the man.\"", [113, 114, 115, 116, 117])
S("s118", "Num 11:10, \"the anger of the Lord blazed hotly, and Moses was displeased\": Moses then complains to God (11:11), the prophet caught between divine anger and the people's weeping.", [118], basis="read")
S("w122", "\"Slow to anger\" (Pro 14:29; 15:18; 16:32; 19:11) is literally \"long of nostrils\", the same idiom as God's self-description in Exo 34:6 (Num 14:18; Neh 9:17; Psa 86:15; 103:8; 145:8; Jon 4:2; Nah 1:3): a human virtue and a divine attribute share one body idiom.", [122], kind="term")
S("w123", "The wisdom sayings treat anger as governable from outside: \"a soft answer turns away wrath\" (Pro 15:1); \"a gift in secret averts anger\" (21:14); \"the wise turn away wrath\" (29:8); \"a wise man will appease\" the king's wrath (16:14); Jam 1:19-20, \"slow to anger; for the anger of man does not produce the righteousness of God\", followed at once by \"the implanted word, which is able to save your souls\" (1:21, seated).", [123, 124, 125, 126, 127])
S("c142", "The inner place is given by a reflexive, \"in himself\" or \"to themselves\" (Est 1:12; Mar 14:4).", [142], basis="read")
S("c144", "The inner place is given by frame words: \"flesh\" (Gal 5; 1Cor 3), \"mind / nous\" (1Ti 6) and \"mouth\" (Col 3:8).", [144], basis="read")
S("c149", "Human anger is repeatedly shown with no seat, carried by act, face, speech, or another person's naming; where the seat appears, it often comes in the next verse, as a consequence or an explanation (Neh 5:7; 1Ki 21:5; 1Sa 1:15).", [149], basis="read")
S("r159", "In Jon 4 the M02 verses (4:1, 4, 9) are no-seat and the seated verse is 4:3 (life); \"angry enough to die\" (Jon 4:3, 9) belongs with the death-wish passages.", [159], basis="read")
S("r160", "1Ki 21:4-5 (Jezebel naming Ahab's spirit) and 1Sa 1:15-16 (Hannah explaining herself) are both one person reading or naming another's inner state.", [160], basis="read")
c.done()
